// ---- story (trick_house 2026-10-19, notes/TRICK_HOUSE.md; GENERATED by b2tools/trick_house.py: edit the generator)
// Sapphire/Ruby data/maps/Route110_TrickHouseEnd/scripts.inc, Emerald's where it differs. The Trick Master = uid 1, NPC
// index 0 (data/story/trick_house.json), at (4,5) facing east; he comes back on every entry (OnWarp addobject). The door
// you came in by (10,1) shuts behind you (OnFrame CloseDoor): its warp (warp 0: you arrive through it, stepping out
// south) is moved off the map once the field is up (TH_X_CloseDoor), so walking into the door does nothing.
// Map scripts: 1027_room_Route110_TrickHouseEnd_init.s. Room tiles = Sapphire + (1, 1).
#define T_MadeItToMe 1
#define T_AllNight0 2
#define T_AllNight1 3
#define T_AllNight2 4
#define T_AllNight3 5
#define T_AllNight4 6
#define T_AllNight5 7
#define T_AllNight6 8
#define T_AllNight7 9
#define T_Earned 10
#define T_NewTricks 11
#define T_NoRoom 12
#define T_RunDry 13
#define T_Journey 14
#define T_Ignoring 15
