L_THX_Exit:                              // TrickMasterExit
    th_vanish TH_TM, FLAG_HIDE_TRICK_HOUSE_END_MAN
    h_addvar VAR_TRICK_HOUSE_ROOMS_COMPLETED, 1
    VMReturn
L_THX_BagFull:                           // BagFull
